package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.phys.Vec3;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.Aspect;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class TravellerBootsAudit {
 static int ticks;static volatile boolean ready,finished;static final BlockPos POS=InfusionAudit.POS;
 static final List<BlockPos> PEDESTALS=List.of(POS.offset(-3,-2,0),POS.offset(3,-2,0),POS.offset(0,-2,3),POS.offset(0,-2,-3),POS.offset(-3,-2,-3),POS.offset(3,-2,3));
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_BOOTS FAIL "+s);System.out.println("TC4_BOOTS PASS "+s);}
 static float air(net.minecraft.world.entity.player.Player p){try{var method=net.minecraft.world.entity.player.Player.class.getDeclaredMethod("getFlyingSpeed");method.setAccessible(true);return (Float)method.invoke(p);}catch(ReflectiveOperationException e){throw new RuntimeException(e);}}
 static void prepare(ServerPlayer p){InfusionAudit.prepare(p);InfusionAudit.matrix.logic.crafting=false;for(int i=0;i<4;i++)BaublesInventory.of(p).setItem(i,ItemStack.EMPTY);p.setItemSlot(EquipmentSlot.FEET,new ItemStack(TravellerBoots.item()));p.getAbilities().flying=false;p.zza=1;p.setYRot(0);p.setOnGround(true);p.setDeltaMovement(Vec3.ZERO);p.fallDistance=4;TravellerBoots.tick(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Pre(p));check(Math.abs(p.getDeltaMovement().z-.055)<.0001&&p.fallDistance==3.75f,"original grounded acceleration and fall distance reduction");check(air(p)==.05f,"native Player mixin uses original .05air control");p.getPersistentData().putBoolean("TC4Hover",true);check(air(p)==.03f,"hover air control .03");p.getPersistentData().remove("TC4Hover");p.zza=0;check(air(p)==.02f,"normal air control restored when not moving forward");p.setDeltaMovement(Vec3.ZERO);p.jumpFromGround();check(Math.abs(p.getDeltaMovement().y-.695)<.0001,"native jump event adds original .275");p.setDeltaMovement(Vec3.ZERO);p.zza=0;p.fallDistance=0;p.getAbilities().flying=true;p.onUpdateAbilities();p.connection.teleport(POS.getX()+7,POS.getY()+3,POS.getZ()-8,40,25);
  var boots=new ItemStack(TravellerBoots.item());check(boots.getMaxDamage()==350&&((ArmorItem)boots.getItem()).getDefense()==1&&boots.getEnchantmentValue()==25,"original durability defence enchantability");var holder=InfusionEnchantmentsHolder(p);check(holder.value().canEnchant(boots)&&RunicAccessories.charge(boots)==0,"repairable and zero innate runic charge");
  var recipe=InfusionItemRecipes.all().stream().filter(r->r.key().equals("BootsTraveller")).findFirst().orElseThrow();for(var fish:List.of(Items.COD,Items.SALMON,Items.TROPICAL_FISH,Items.PUFFERFISH)){var parts=recipe.componentStacks();parts.set(5,new ItemStack(fish));check(InfusionItemRecipes.match(parts,new ItemStack(Items.LEATHER_BOOTS),Set.of("BOOTSTRAVELLER"))==recipe,"original wildcard rawfish accepted "+fish);check(thaumcraft.common.tiles.infusion.InfusionMatrixLogic.sameIngredient(parts.get(5),recipe.componentStacks().get(5)),"wildcard fish consumption "+fish);}var bad=recipe.componentStacks();bad.set(5,new ItemStack(Items.COOKED_COD));check(InfusionItemRecipes.match(bad,new ItemStack(Items.LEATHER_BOOTS),Set.of("BOOTSTRAVELLER"))==null,"cooked fish rejected");check(InfusionItemRecipes.match(recipe.componentStacks(),new ItemStack(Items.LEATHER_BOOTS),Set.of())==null,"research gate");
  var l=p.serverLevel();((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).setItem(new ItemStack(Items.LEATHER_BOOTS));var parts=recipe.componentStacks();parts.set(5,new ItemStack(Items.SALMON));for(int i=0;i<6;i++){l.setBlock(PEDESTALS.get(i),InfusionContent.PEDESTAL.get().defaultBlockState(),3);((InfusionContent.PedestalEntity)l.getBlockEntity(PEDESTALS.get(i))).setItem(parts.get(i));}for(int dx:new int[]{-1,1})l.setBlock(POS.offset(dx,-2,-4),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);int i=0;for(var a:recipe.aspects().getAspects()){var pos=POS.offset(i++*4-2,-2,-4);l.setBlock(pos,EssentiaDevices.JAR.get().defaultBlockState(),3);var jar=(WardedJarEntity)l.getBlockEntity(pos);jar.state.aspect=a;jar.state.amount=25;jar.changed();}InfusionAudit.click(p,p.getInventory().items.stream().filter(WandData::isWand).findFirst().orElseThrow());check(InfusionAudit.matrix.logic.crafting&&InfusionAudit.matrix.logic.recipeEssentia.visSize()==50&&InfusionAudit.matrix.logic.recipeIngredients.size()==6,"actual wand starts six-component50essentia boots infusion");ready=true;
 }
 static net.minecraft.core.Holder<net.minecraft.world.item.enchantment.Enchantment> InfusionEnchantmentsHolder(ServerPlayer p){return p.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(BasicsEnchantments.REPAIR);}
 static void finish(ServerPlayer p){var l=p.serverLevel();var out=((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).item();check(!InfusionAudit.matrix.logic.crafting&&out.is(TravellerBoots.item()),"natural altar crafts traveller boots with salmon wildcard");for(var pos:PEDESTALS)check(((InfusionContent.PedestalEntity)l.getBlockEntity(pos)).item().isEmpty(),"component consumed "+pos);for(int dx:new int[]{-2,2})check(((WardedJarEntity)l.getBlockEntity(POS.offset(dx,-2,-4))).state.amount==0,"exact25essentia consumed "+dx);finished=true;}
 static void client(net.minecraft.client.Minecraft mc){check(ready,"setup complete");var p=mc.player;check(TravellerBoots.worn(p),"boots equipment sync");var step=p.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.STEP_HEIGHT);double old=TravellerBoots.oldStep.getOrDefault(p,step.getBaseValue());p.getAbilities().flying=false;p.zza=1;TravellerBoots.tick(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Pre(p));check(step.getBaseValue()==1,"client step height becomes1");p.input.shiftKeyDown=true;p.setShiftKeyDown(true);TravellerBoots.tick(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Pre(p));check(step.getBaseValue()==old,"sneaking restores original step height");p.input.shiftKeyDown=false;p.setShiftKeyDown(false);p.zza=0;p.getAbilities().flying=true;check(mc.getResourceManager().getResource(AlchemyContent.id("textures/models/bootstraveler.png")).isPresent(),"original worn texture available");mc.options.setCameraType(net.minecraft.client.CameraType.THIRD_PERSON_BACK);}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.bootsAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var s=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)s.execute(()->prepare(s.getPlayerList().getPlayer(id)));if(ticks==140)client(mc);if(ticks==150)LiquidDeathAudit.shot(mc,"traveller-boots-worn.png");if(ticks==160&&Boolean.getBoolean("tc4modern.bootsQuickAuditOnly")){mc.stop();return;}if(ticks==250)LiquidDeathAudit.shot(mc,"traveller-boots-infusion.png");if(ticks==1100)s.execute(()->finish(s.getPlayerList().getPlayer(id)));if(ticks==1110){check(finished,"infusion complete");LiquidDeathAudit.shot(mc,"traveller-boots-finished.png");var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("BOOTSTRAVELLER"),0);mc.setScreen(book);}if(ticks==1120)LiquidDeathAudit.shot(mc,"traveller-boots-book.png");if(ticks==1130)mc.stop();}
}
